command:
stats(){
 for p in /sys/fs/cgroup/cpu.stat /sys/fs/cgroup/cpu/cpu.stat /sys/fs/cgroup/cpu,cpuacct/cpu.stat; do
  if [ -r "$p" ]; then
   echo "# cgroup counters $p"; cat "$p";
   if [ -r "${p%/*}/cpuacct.usage" ]; then printf 'usage_nsec '; cat "${p%/*}/cpuacct.usage"; fi
   return;
  fi;
 done;
 echo '# cgroup CPU counters unavailable';
};
cpus=$(taskset -pc $$ | sed "s/.*: //");
first=$(echo "$cpus" | cut -d, -f1 | cut -d- -f1); second=$((first+1));
echo "# allowed CPUs $cpus; benchmark CPU $first"; stats;
taskset -c $second true || exit 42; echo "# load CPU $second"; taskset -c $second sh -c "while :; do :; done" & load=$!; cleanup(){ kill "$load" 2>/dev/null || :; wait "$load" 2>/dev/null || :; }; trap cleanup EXIT; taskset -c "$first" java -Xms512m -Xmx512m -cp /out/library:/out/harness:/opt/jmh/commons-math3-3.6.1.jar:/opt/jmh/jmh-core-1.37.jar:/opt/jmh/jmh-generator-annprocess-1.37.jar:/opt/jmh/jopt-simple-5.0.4.jar org.openjdk.jmh.Main perflens.external.RankBenchmark.rank -f 1 -t 1 -wi 3 -i 3 -w 200ms -r 300ms -rf json -rff /out/mitigation-3-1.json -p limit=65534 -p containers=16; status=$?; cleanup; trap - EXIT; stats; exit "$status"
